package com.nigson.commerce.payment;
import java.util.*;
import java.time.*;
import java.math.BigDecimal;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.support.*;
import com.nigson.commerce.order.*;
import com.nigson.commerce.platform.*;
import com.nigson.commerce.payment.internal.infrastructure.external.paystack.PaystackAdapter;
import com.nigson.shared.events.EventCodec;
import com.nigson.shared.problem.*;
import com.nigson.shared.security.ProviderHttp;
import tools.jackson.databind.JsonNode;
/** Persist intent, release locks, call the qualified HTTP adapter, then persist outcomes. */
public final class CheckoutPaymentCoordinator implements CheckoutPayments {
 private final JdbcTemplate jdbc;private final TransactionTemplate tx;private final PaystackAdapter provider;private final OrderPolicy policy;private final OrderLifecycle orders;private final AuditWriter audit;private final Clock clock;private final io.micrometer.core.instrument.MeterRegistry metrics;
 public CheckoutPaymentCoordinator(JdbcTemplate jdbc,PlatformTransactionManager manager,PaystackAdapter provider,OrderPolicy policy,OrderLifecycle orders,AuditWriter audit,Clock clock,io.micrometer.core.instrument.MeterRegistry metrics){this.jdbc=jdbc;this.tx=new TransactionTemplate(manager);tx.setTimeout(2);this.provider=provider;this.policy=policy;this.orders=orders;this.audit=audit;this.clock=clock;this.metrics=metrics;}
 public void requireReady(){if(!policy.enabled()||provider==null)throw new Problem.Failure(ProblemCode.FEATURE_DISABLED);}
 private record Attempt(UUID id,UUID order,String reference,String amount,String email,String state,Instant lease,long version){}
 private Attempt locked(UUID order){jdbc.execute("SET LOCAL lock_timeout='500ms'");jdbc.execute("SET LOCAL statement_timeout='2s'");var owned=jdbc.queryForList("SELECT o.status,o.currency_code,o.grand_total,o.carrier_snapshot->>'mode' AS carrier_mode,p.email FROM commerce.sales_order o JOIN commerce.party p ON p.id=o.party_id WHERE o.id=? FOR UPDATE OF o",order);if(owned.size()!=1)throw new Problem.Failure(ProblemCode.NOT_FOUND);var row=owned.getFirst();policy.require(row.get("carrier_mode").toString());var attempts=jdbc.queryForList("SELECT * FROM commerce.payment_attempt WHERE order_id=? ORDER BY created_at DESC,id DESC LIMIT 1 FOR UPDATE",order);if(attempts.size()!=1)throw OrderValues.rule();var a=attempts.getFirst();if(!a.get("provider").equals("PAYSTACK")||!a.get("merchant_account").equals(policy.merchantAccount())||!a.get("provider_mode").equals(policy.mode())||!a.get("currency_code").equals("NGN")||!a.get("currency_code").equals(row.get("currency_code"))||((BigDecimal)a.get("expected_amount")).compareTo((BigDecimal)row.get("grand_total"))!=0)throw new Problem.Failure(ProblemCode.PROVIDER_MODE_MISMATCH);return new Attempt((UUID)a.get("id"),order,a.get("reference").toString(),((BigDecimal)a.get("expected_amount")).setScale(2,java.math.RoundingMode.UNNECESSARY).toPlainString(),row.get("email").toString(),a.get("state").toString(),a.get("initiating_until")==null?null:((java.sql.Timestamp)a.get("initiating_until")).toInstant(),((Number)a.get("version")).longValue());}
 private void evidence(Attempt before,String state,UUID correlation,boolean verify){audit.append("payment-coordinator",AuditValues.ActorKind.SYSTEM,verify?AuditValues.Action.PAYMENT_VERIFICATION:AuditValues.Action.PAYMENT_INITIATION,AuditValues.Resource.ORDER,before.order(),correlation,verify?AuditValues.Reason.VERIFIED_PROVIDER:AuditValues.Reason.OPERATOR_REQUEST,Map.of("state",before.state(),"version",before.version()),Map.of("state",state,"version",before.version()+1,"providerMode",policy.mode()),null);TransactionSynchronizationManager.registerSynchronization(new TransactionSynchronization(){public void afterCommit(){metrics.counter("nigson.payment.outcomes","state",state).increment();}});}
 private void state(Attempt before,String state,String url,boolean verified,UUID correlation,boolean verification){if(before.version()==Long.MAX_VALUE)throw OrderValues.rule();jdbc.update("UPDATE commerce.payment_attempt SET state=?,checkout_url=coalesce(?,checkout_url),initiating_until=NULL,verified_at=CASE WHEN ? THEN ? ELSE verified_at END,next_reconcile_at=?,version=version+1,updated_at=?,updated_by='payment-coordinator' WHERE id=?",state,url,verified,java.sql.Timestamp.from(clock.instant()),Set.of("PENDING","UNKNOWN").contains(state)?java.sql.Timestamp.from(clock.instant().plusSeconds(30)):null,java.sql.Timestamp.from(clock.instant()),before.id());evidence(before,state,correlation,verification);}
 public void initialize(UUID order,UUID correlation){requireReady();if(TransactionSynchronizationManager.isActualTransactionActive())throw new IllegalStateException("PROVIDER_CALL_INSIDE_TRANSACTION");Attempt attempt=tx.execute(status->{var a=locked(order);if(!a.state().equals("CREATED")){if(a.state().equals("INITIATING")&&(a.lease()==null||!a.lease().isAfter(clock.instant())))state(a,"UNKNOWN",null,false,correlation,false);return null;}if(!jdbc.queryForObject("SELECT status='PENDING' AND payment_status='UNPAID' FROM commerce.sales_order WHERE id=?",Boolean.class,order))throw new Problem.Failure(ProblemCode.INVALID_TRANSITION);if(a.version()==Long.MAX_VALUE)throw OrderValues.rule();PaystackAdapter.kobo(a.amount());if(a.email().length()>254||!a.email().matches("[^\\s@]+@[^\\s@]+\\.[^\\s@]+"))throw OrderValues.rule();jdbc.update("UPDATE commerce.payment_attempt SET state='INITIATING',initiating_until=?,next_reconcile_at=?,version=version+1,updated_at=?,updated_by='payment-coordinator' WHERE id=?",java.sql.Timestamp.from(clock.instant().plusSeconds(30)),java.sql.Timestamp.from(clock.instant().plusSeconds(30)),java.sql.Timestamp.from(clock.instant()),a.id());jdbc.update("UPDATE commerce.sales_order SET payment_status='PENDING',version=version+1,updated_at=?,updated_by='payment-coordinator' WHERE id=?",java.sql.Timestamp.from(clock.instant()),order);evidence(a,"INITIATING",correlation,false);return a;});if(attempt==null)return;
  String url=null;boolean accepted=false;try{url=provider.initialize(attempt.reference(),attempt.email(),attempt.amount()).path("authorization_url").asString();var uri=java.net.URI.create(url);if(url.length()>1000||uri.getFragment()!=null||uri.getUserInfo()!=null||(policy.mode().equals("MOCK")?!uri.getScheme().equals("http")||!uri.getHost().equals("paystack-mock")||uri.getPort()!=8080:!uri.getScheme().equals("https")||!uri.getHost().equals("checkout.paystack.com")||!Set.of(-1,443).contains(uri.getPort())))throw OrderValues.rule();accepted=true;}catch(ProviderHttp.Failure|Problem.Failure|IllegalArgumentException uncertain){accepted=false;}
  final String hosted=url;final boolean success=accepted;tx.executeWithoutResult(status->{var current=locked(order);if(!current.id().equals(attempt.id())||!current.state().equals("INITIATING"))return;state(current,success?"PENDING":"UNKNOWN",success?hosted:null,false,correlation,false);});
 }
 public void inspect(UUID order,UUID correlation){requireReady();if(TransactionSynchronizationManager.isActualTransactionActive())throw new IllegalStateException("PROVIDER_CALL_INSIDE_TRANSACTION");Attempt attempt=tx.execute(status->{var a=locked(order);if(a.state().equals("CREATED")){state(a,"CANCELLED",null,true,correlation,true);return null;}if(a.state().equals("SUCCEEDED")||a.state().equals("CANCELLED")||a.state().equals("FAILED")&&Boolean.TRUE.equals(jdbc.queryForObject("SELECT verified_at IS NOT NULL FROM commerce.payment_attempt WHERE id=?",Boolean.class,a.id())))return null;if(a.state().equals("INITIATING")&&a.lease()!=null&&a.lease().isAfter(clock.instant()))return null;return a;});if(attempt==null)return;
  JsonNode data;try{data=provider.verify(attempt.reference(),PaystackAdapter.kobo(attempt.amount()));}catch(ProviderHttp.Failure|IllegalArgumentException uncertain){tx.executeWithoutResult(status->{var current=locked(order);if(current.id().equals(attempt.id())&&!Set.of("SUCCEEDED","FAILED","CANCELLED").contains(current.state())&&!current.state().equals("UNKNOWN"))state(current,"UNKNOWN",null,false,correlation,true);});return;}
  String outcome=data.path("status").asString();String verifiedTransaction=null,verifiedHash=null;Instant verifiedPaid=null;if(outcome.equals("success")){try{verifiedTransaction=transactionId(data);verifiedPaid=paidAt(data);verifiedHash=EventCodec.hash(data);}catch(Problem.Failure|IllegalArgumentException malformed){tx.executeWithoutResult(status->{var current=locked(order);if(current.id().equals(attempt.id())&&!Set.of("SUCCEEDED","FAILED","CANCELLED","UNKNOWN").contains(current.state()))state(current,"UNKNOWN",null,false,correlation,true);});return;}}final String transaction=verifiedTransaction,hash=verifiedHash;final Instant paid=verifiedPaid;tx.executeWithoutResult(status->{var current=locked(order);if(!current.id().equals(attempt.id())||Set.of("SUCCEEDED","CANCELLED").contains(current.state()))return;if(outcome.equals("success")){var existing=jdbc.queryForList("SELECT provider_transaction_id,verification_hash FROM commerce.payment_transaction WHERE attempt_id=?",current.id());if(existing.isEmpty())jdbc.update("INSERT INTO commerce.payment_transaction(id,created_by,attempt_id,provider_transaction_id,settled_amount,currency_code,provider_status,settled_at,verification_hash,provider_mode) VALUES (?,'payment-coordinator',?, ?,?,'NGN','success',?,?,?)",EventCodec.uuid7(clock.instant()),current.id(),transaction,new BigDecimal(current.amount()),java.sql.Timestamp.from(paid),hash,policy.mode());else if(!existing.getFirst().get("provider_transaction_id").equals(transaction))throw OrderValues.rule();state(current,"SUCCEEDED",null,true,correlation,true);orders.settled(order,correlation);}else if(Set.of("failed","abandoned","reversed").contains(outcome)){state(current,"FAILED",null,true,correlation,true);if(!Boolean.TRUE.equals(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM commerce.payment_transaction WHERE attempt_id=?)",Boolean.class,current.id())))jdbc.update("UPDATE commerce.sales_order SET payment_status='FAILED',version=version+1,updated_at=?,updated_by='payment-coordinator' WHERE id=? AND status='PENDING'",java.sql.Timestamp.from(clock.instant()),order);}else state(current,"PENDING",null,false,correlation,true);});
 }
 private String transactionId(JsonNode data){var id=data.get("id");if(id==null||!(id.isIntegralNumber()||policy.mode().equals("MOCK")&&id.isString()))throw OrderValues.rule();String value=id.isString()?id.asString():id.toString();if(!value.matches("[A-Za-z0-9][A-Za-z0-9_-]{0,119}")||value.equals("0"))throw OrderValues.rule();return value;}
 private Instant paidAt(JsonNode data){var node=data.get("paid_at");if(node==null||!node.isString())throw OrderValues.rule();Instant time=ApiValues.instant(node.asString());if(time.isBefore(Instant.EPOCH)||time.isAfter(clock.instant()))throw OrderValues.rule();return time;}
}
